var lcOpc=null,lcIt=null,lcMod='',lcLocal='',lcRep='',lcSec='';
function lcLink(it,mod){ // linha embaixo do item: link ou "aguardando o Celio"
  if(it.sug)return '<div class="lcAg">📍 sugerido por '+esc(it.sug.quem)+': <b>'+esc(it.sug.local)+'</b> · '+esc(it.sug.rep)+' — aguardando o Celio</div>';
  return '<button class="lcLk">📍 não fica aqui / não é meu</button>';
}
function lcLigar(li,it,mod){var b=li.querySelector('.lcLk');if(b)b.onclick=function(e){e.stopPropagation();abrirLocal(it,mod);};}
function abrirLocal(it,mod){
  vibra();lcIt=it;lcMod=mod;lcLocal='';lcRep='';lcSec='';
  $('lcProd').textContent=it.desc;$('lcAntes').textContent='hoje: '+(it.local||'sem local')+' · '+((mod==='CV'?it.rep:it.quem)||'sem repositora');
  $('lcBusca').value='';$('lcRes').innerHTML='';$('lcBuscaBox').style.display='none';$('lcObs').value='';
  $('cardLocal').classList.add('on');lcMontar();
  if(!lcOpc)api({acao:'locaisOpcoes',quem:quem,token:token}).then(function(r){if(r&&r.ok){lcOpc={locais:r.locais||[],reps:r.reps||[]};lcMontar();}else if(r&&r.reauth){irPin();}}).catch(function(){toast('Sem conexão','err');});
}
function lcMontar(){
  var bl=$('lcLocais'),br=$('lcReps');bl.innerHTML='';br.innerHTML='';
  if(!lcOpc){bl.innerHTML='<span class="lcCar">carregando…</span>';return;}
  var top=lcOpc.locais.slice(0,10).map(function(x){return x.local;});
  if(lcLocal&&top.indexOf(lcLocal)<0)top.unshift(lcLocal);
  top.forEach(function(l){var s=document.createElement('button');s.textContent=l;s.className=l===lcLocal?'on':'';s.onclick=function(){lcEscolher(l);};bl.appendChild(s);});
  var o=document.createElement('button');o.textContent='🔎 outro local…';o.className='ou';o.onclick=function(){$('lcBuscaBox').style.display='block';$('lcBusca').focus();};bl.appendChild(o);
  lcOpc.reps.forEach(function(p){var s=document.createElement('button');s.textContent=p;s.className=p===lcRep?'on':'';s.onclick=function(){vibra();lcRep=p;lcMontar();};br.appendChild(s);});
}
function lcEscolher(l){vibra();lcLocal=l;var o=(lcOpc.locais||[]).filter(function(x){return x.local===l;})[0];lcSec=o?o.secao:'';if(o&&o.rep)lcRep=o.rep;$('lcBuscaBox').style.display='none';$('lcRes').innerHTML='';lcMontar();}
$('lcBusca').addEventListener('input',function(){
  var t=semAc(this.value).toLowerCase().trim(),ul=$('lcRes');ul.innerHTML='';if(!t||!lcOpc)return;
  lcOpc.locais.filter(function(x){return semAc(x.local).toLowerCase().indexOf(t)>=0;}).slice(0,8).forEach(function(x){var li=document.createElement('li');li.innerHTML='<span>'+esc(x.local)+'</span><small>'+esc(x.rep)+'</small>';li.onclick=function(){lcEscolher(x.local);};ul.appendChild(li);});
  var v=this.value.trim(),li2=document.createElement('li');li2.innerHTML='<span>usar como escrevi: "'+esc(v)+'"</span>';li2.onclick=function(){lcEscolher(v);};ul.appendChild(li2);
});
function lcEnviar(){
  if(!lcLocal)return toast('Escolha onde o produto fica','err');if(!lcRep)return toast('Escolha quem repõe','err');
  var it=lcIt,b=$('lcBt');b.disabled=true;
  api({acao:'localSugerir',quem:quem,token:token,modulo:lcMod,sku:it.sku||'',desc:it.desc,localAntes:it.local||'',repAntes:(lcMod==='CV'?it.rep:it.quem)||'',local:lcLocal,rep:lcRep,secao:lcSec,obs:$('lcObs').value.trim()}).then(function(r){
    b.disabled=false;
    if(r&&r.ok){vibra();it.sug=r.sug;$('cardLocal').classList.remove('on');toast('Enviado — o Celio vai aprovar','ok');if(lcMod==='CV'){renderVAL();carregarVAL();}else{renderPSV();carregarPSV();}}
    else if(r&&r.reauth){toast('Sessão expirada — digite o PIN de novo','err');try{localStorage.removeItem('ci_token');}catch(e){}irPin();}
    else toast((r&&r.erro)||'Não deu','err');
  }).catch(function(){b.disabled=false;toast('Sem conexão, tente de novo','err');});
}
function lcAprovar(box,lista,mod){ // bloco "LOCAIS A APROVAR" (só o Celio)
  if(!lista||!lista.length)return;
  var hd=document.createElement('div');hd.className='grp tg lcHd';hd.innerHTML='<span>📍 LOCAIS A APROVAR ('+lista.length+')</span>';box.appendChild(hd);
  lista.forEach(function(x){
    var d=document.createElement('div');d.className='lcAp';
    d.innerHTML='<div class="q">'+esc(x.quem)+' · '+esc(String(x.data).slice(0,16))+(x.modulo==='CV'?' · validades':' · sem venda')+'</div><div class="d">'+esc(x.desc)+'</div><div class="t"><s>'+esc(x.localAntes||'sem local')+' · '+esc(x.repAntes||'—')+'</s><br>➜ <b>'+esc(x.local)+' · '+esc(x.rep)+'</b>'+(x.secao?' <small>('+esc(x.secao)+')</small>':'')+'</div>'+(x.obs?'<div class="o">“'+esc(x.obs)+'”</div>':'')+'<div class="bts"><button class="sim">✓ APROVAR</button><button class="nao">RECUSAR</button></div>';
    function dec(ap,b){vibra();b.textContent='…';d.querySelectorAll('button').forEach(function(z){z.disabled=true;});
      api({acao:'localDecidir',quem:quem,token:token,id:x.id,aprovar:ap?'1':''}).then(function(r){
        if(r&&r.ok){toast(ap?'Aprovado — cadastro corrigido':'Recusado','ok');if(mod==='CV'){valCache.locais=r.pend||[];carregarVAL();renderVAL();}else{psvCache.locais=r.pend||[];carregarPSV();renderPSV();}}
        else{toast((r&&r.erro)||'Não deu','err');d.querySelectorAll('button').forEach(function(z){z.disabled=false;});b.textContent=ap?'✓ APROVAR':'RECUSAR';}
      }).catch(function(){toast('Sem conexão','err');d.querySelectorAll('button').forEach(function(z){z.disabled=false;});b.textContent=ap?'✓ APROVAR':'RECUSAR';});}
    var bs=d.querySelector('.sim'),bn=d.querySelector('.nao');bs.onclick=function(){dec(true,bs);};bn.onclick=function(){dec(false,bn);};
    box.appendChild(d);
  });
}

